const baseUrl = process.env.SMOKE_APP_BASE_URL ?? 'http://127.0.0.1:3100';

const forbiddenEverywhere = [
  'command center',
  'mission control',
  'ai dashboard',
  'smart review',
  'chatgpt',
  'openai',
  'ai-generated',
  'generated by ai',
  'Operational Reporting Dashboard',
  'Field Submission Workflow',
  'Location Review and Registry Readiness',
  'Registry Administration',
  'Language selection',
  'pilot-mvp',
  'demo access',
  'Rows JSON',
  'http://localhost:8100',
  'http://api:8100',
];

const pages = [
  {
    path: '/',
    required: [
      'National Addressing Platform',
      'Use this service to register a location, check an official address code, or track a submitted request.',
      'Register a location',
      'Check address code',
      'Track a request',
      'How a location becomes official',
      'Staff sign-in',
    ],
  },
  {
    path: '/geotag',
    required: ['Register location', 'Submit location for review'],
  },
  {
    path: '/issue',
    required: ['Check address code', 'Search the public registry'],
  },
  {
    path: '/track',
    required: ['Track request', 'Tracking code'],
    forbidden: ['citizen_contact', 'dip_last4', 'admin123'],
  },
  {
    path: '/workspace',
    required: [
      'National Operations',
      'Today’s addressing work',
      'Developed by BeCoreOps for the Government of the Republic of Equatorial Guinea',
    ],
  },
  {
    path: '/field',
    required: [
      'Field Operations',
      'Coordinate assignments, inspect mapped locations, capture GNSS evidence, and synchronize verified field work into the protected review flow.',
      'Valid next actions',
      'Field capture does not create a public address',
    ],
  },
  {
    path: '/registry',
    required: [
      'Address Registry',
      'Search, inspect, create, update, and route official address records from one controlled workspace.',
      'Valid next actions',
      'Developed by BeCoreOps for the Government of the Republic of Equatorial Guinea',
    ],
  },
  {
    path: '/verify',
    required: [
      'Verification',
      'Review submitted evidence, resolve exceptions, and make authoritative decisions without leaving the case workspace.',
      'Decision inspector',
      'Approval is not publication',
    ],
  },
  {
    path: '/signage',
    required: [
      'Publication',
      'Resolve release blockers, hold verified records, simulate institutional approval, and prepare controlled public and physical outputs.',
      'Valid next actions',
      'Preparation, approval, publication, and signage are separate states',
    ],
  },
  {
    path: '/admin/staff',
    required: [
      'Administration',
      'Manage authorized personnel, roles, account state, and active sessions from one protected personnel register.',
      'Least privilege remains the default',
    ],
  },
  {
    path: '/exports',
    required: [
      'Publication Outputs',
      'Publication',
      'Official outputs',
      'Preparation, approval, publication, and signage are separate states',
    ],
  },
  {
    path: '/reports',
    required: ['Reports', 'Reports are read-only', 'Track workload, review progress, field activity, and publication readiness.'],
  },
  {
    path: '/login',
    required: ['Staff sign-in', 'Sign in to perform protected registry actions'],
    forbidden: ['Pilot Admin Sign-In', 'admin123', 'editor123', 'viewer123'],
  },
];

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

for (const page of pages) {
  const response = await fetch(`${baseUrl}${page.path}`, { redirect: 'follow' });
  assert(response.ok, `${page.path} returned ${response.status}`);
  const html = (await response.text()).toLowerCase().replaceAll('&amp;', '&');
  for (const phrase of page.required) {
    assert(html.includes(phrase.toLowerCase()), `${page.path} missing required phrase: ${phrase}`);
  }
  for (const phrase of [...forbiddenEverywhere, ...(page.forbidden ?? [])]) {
    assert(!html.includes(phrase.toLowerCase()), `${page.path} contains forbidden phrase: ${phrase}`);
  }
  console.log(`ok ${page.path}`);
}

console.log('page copy guard passed');
